CREATE FUNCTION public.org_is_active_user(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=_uid AND status='active') $$;
CREATE FUNCTION public.org_user_dept(_uid uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT department_id FROM public.profiles WHERE id=_uid $$;
CREATE FUNCTION public.org_valid_assignments(_user uuid) RETURNS TABLE(id uuid,role_id uuid,department_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT ur.id,ur.role_id,ur.department_id FROM public.org_user_roles ur JOIN public.org_roles r ON r.id=ur.role_id AND r.is_active WHERE ur.user_id=_user AND ur.revoked_at IS NULL AND ur.valid_from<=now() AND (ur.valid_until IS NULL OR ur.valid_until>now()) $$;
CREATE FUNCTION public.org_unresolved_conflicts(_user uuid) RETURNS TABLE(rule_id uuid,role_a_id uuid,role_b_id uuid,severity text,description text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT s.id,s.role_a_id,s.role_b_id,s.severity,s.description FROM public.org_sod_rules s WHERE s.is_active AND EXISTS(SELECT 1 FROM public.org_valid_assignments(_user) a WHERE a.role_id=s.role_a_id) AND EXISTS(SELECT 1 FROM public.org_valid_assignments(_user) a WHERE a.role_id=s.role_b_id) AND NOT EXISTS(SELECT 1 FROM public.org_sod_exceptions e WHERE e.kind='rol' AND e.user_id=_user AND e.rule_id=s.id AND e.revoked_at IS NULL AND e.starts_at<=now() AND e.expires_at>now()) $$;
CREATE FUNCTION public.org_sod_conflicts_if(_user uuid,_new uuid[],_also uuid[] DEFAULT '{}') RETURNS TABLE(rule_id uuid,severity text,description text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ WITH held AS (SELECT a.role_id FROM public.org_valid_assignments(_user) a UNION SELECT unnest(coalesce(_also,'{}'::uuid[])) UNION SELECT unnest(coalesce(_new,'{}'::uuid[]))) SELECT s.id,s.severity,s.description FROM public.org_sod_rules s WHERE s.is_active AND s.role_a_id IN(SELECT role_id FROM held) AND s.role_b_id IN(SELECT role_id FROM held) AND (s.role_a_id=ANY(coalesce(_new,'{}'::uuid[])) OR s.role_b_id=ANY(coalesce(_new,'{}'::uuid[]))) AND NOT EXISTS(SELECT 1 FROM public.org_sod_exceptions e WHERE e.kind='rol' AND e.user_id=_user AND e.rule_id=s.id AND e.revoked_at IS NULL AND e.starts_at<=now() AND e.expires_at>now()) $$;
CREATE FUNCTION public.org_effective_permissions(_user uuid) RETURNS TABLE(resource text,action public.org_action,scope public.org_scope,department_id uuid,role_id uuid,role_code text,role_name text,assignment_id uuid,require_mfa boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ WITH conflicted AS(SELECT c.role_a_id rid FROM public.org_unresolved_conflicts(_user) c UNION SELECT c.role_b_id FROM public.org_unresolved_conflicts(_user) c) SELECT p.resource,p.action,p.scope,CASE WHEN p.scope='departamento' THEN coalesce(a.department_id,public.org_user_dept(_user)) END,r.id,r.code,r.name,a.id,rp.require_mfa FROM public.org_valid_assignments(_user) a JOIN public.org_roles r ON r.id=a.role_id JOIN public.org_role_permissions rp ON rp.role_id=r.id JOIN public.org_permissions p ON p.id=rp.permission_id WHERE public.org_is_active_user(_user) AND a.role_id NOT IN(SELECT rid FROM conflicted) AND NOT EXISTS(SELECT 1 FROM public.org_user_denies d WHERE d.user_id=_user AND d.permission_id=p.id) AND (p.scope<>'departamento' OR EXISTS(SELECT 1 FROM public.departments d WHERE d.id=coalesce(a.department_id,public.org_user_dept(_user)) AND d.is_active)) $$;
CREATE FUNCTION public.org_check(_user uuid,_resource text,_action public.org_action,_dept uuid DEFAULT NULL,_owner uuid DEFAULT NULL,_any_scope boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT CASE WHEN _user IS NULL OR NOT public.org_is_active_user(_user) THEN false WHEN public.is_ceo(_user) AND _action<>'auditar' THEN true ELSE EXISTS(SELECT 1 FROM public.org_effective_permissions(_user) e WHERE e.resource=_resource AND e.action=_action AND (NOT e.require_mfa OR _user IS DISTINCT FROM auth.uid() OR coalesce(auth.jwt()->>'aal','')='aal2') AND (_any_scope OR e.scope='global' OR (e.scope='departamento' AND _dept IS NOT NULL AND e.department_id=_dept) OR (e.scope='propio' AND _owner IS NOT NULL AND _owner=_user))) END $$;
CREATE FUNCTION public.org_actor() RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE u uuid:=auth.uid(); BEGIN IF u IS NULL OR NOT public.org_is_active_user(u) THEN RAISE EXCEPTION 'No autorizado' USING errcode='42501'; END IF; RETURN u; END $$;
CREATE FUNCTION public.org_assert_admin(_resource text) RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE u uuid:=public.org_actor(); BEGIN IF NOT public.is_ceo(u) THEN RAISE EXCEPTION 'Solo el CEO puede administrar departamentos, cargos, roles y permisos' USING errcode='42501'; END IF; RETURN u; END $$;
CREATE FUNCTION public.org_need_reason(_reason text) RETURNS void LANGUAGE plpgsql IMMUTABLE SET search_path=public,pg_temp AS $$ BEGIN IF char_length(btrim(coalesce(_reason,'')))<5 THEN RAISE EXCEPTION 'Indica un motivo (mínimo 5 caracteres)'; END IF; END $$;
CREATE FUNCTION public.org_role_is_privileged(_role uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT coalesce((SELECT r.is_privileged FROM public.org_roles r WHERE r.id=_role),false) OR EXISTS(SELECT 1 FROM public.org_role_permissions rp JOIN public.org_permissions p ON p.id=rp.permission_id WHERE rp.role_id=_role AND p.action IN('administrar','aprobar','auditar')) $$;
CREATE FUNCTION public.org_log(_action text,_entity text,_entity_id text,_before jsonb,_after jsonb,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.org_authz_config c WHERE c.id=1 AND c.require_mfa_admin) AND coalesce(auth.jwt()->>'aal','')<>'aal2' THEN RAISE EXCEPTION 'Esta operación requiere verificación en dos pasos (MFA)' USING errcode='42501'; END IF; INSERT INTO public.org_change_log(actor_id,actor_email,action,entity,entity_id,before_data,after_data,reason) VALUES(auth.uid(),(SELECT email FROM public.profiles WHERE id=auth.uid()),_action,_entity,_entity_id,_before,_after,_reason); PERFORM public.write_audit('org.'||_action,_entity||':'||coalesce(_entity_id,''),jsonb_build_object('reason',_reason,'after',_after)); END $$;
CREATE FUNCTION public.org_my_permissions() RETURNS TABLE(resource text,action public.org_action,scope public.org_scope,department_id uuid,require_mfa boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE u uuid:=auth.uid(); BEGIN IF u IS NULL OR NOT public.org_is_active_user(u) THEN RETURN; END IF; IF public.is_ceo(u) THEN RETURN QUERY SELECT p.resource,p.action,p.scope,NULL::uuid,false FROM public.org_permissions p WHERE p.scope='global' AND p.action<>'auditar'; RETURN; END IF; RETURN QUERY SELECT e.resource,e.action,e.scope,e.department_id,e.require_mfa FROM public.org_effective_permissions(u) e; END $$;
CREATE FUNCTION public.org_user_effective_permissions(_user uuid) RETURNS TABLE(resource text,action public.org_action,scope public.org_scope,department_id uuid,role_code text,role_name text,assignment_id uuid,require_mfa boolean,source text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE u uuid:=public.org_actor(); BEGIN IF _user IS DISTINCT FROM u AND NOT(public.is_ceo(u) OR public.org_check(u,'usuarios','consultar',public.org_user_dept(_user),NULL) OR public.org_check(u,'permisos','consultar')) THEN RAISE EXCEPTION 'No autorizado' USING errcode='42501'; END IF; IF public.is_ceo(_user) THEN RETURN QUERY SELECT p.resource,p.action,p.scope,NULL::uuid,'ceo'::text,'CEO (facultad global)'::text,NULL::uuid,false,'ceo'::text FROM public.org_permissions p WHERE p.scope='global' AND p.action<>'auditar'; RETURN; END IF; RETURN QUERY SELECT e.resource,e.action,e.scope,e.department_id,e.role_code,e.role_name,e.assignment_id,e.require_mfa,'rol'::text FROM public.org_effective_permissions(_user) e; END $$;
CREATE FUNCTION public.org_user_conflicts(_user uuid) RETURNS TABLE(rule_id uuid,role_a_id uuid,role_b_id uuid,severity text,description text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE u uuid:=public.org_actor(); BEGIN IF _user IS DISTINCT FROM u AND NOT(public.is_ceo(u) OR public.org_check(u,'usuarios','consultar',public.org_user_dept(_user),NULL)) THEN RAISE EXCEPTION 'No autorizado' USING errcode='42501'; END IF; RETURN QUERY SELECT * FROM public.org_unresolved_conflicts(_user); END $$;
CREATE FUNCTION public.org_upsert_department(_id uuid,_code text,_name text,_description text,_parent_id uuid,_sort int) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('departamentos'); old public.departments; rid uuid; BEGIN _code:=lower(btrim(coalesce(_code,''))); _name:=btrim(coalesce(_name,'')); IF _code !~ '^[a-z0-9_]{2,40}$' THEN RAISE EXCEPTION 'Código inválido (a-z, 0-9, _; 2-40)'; END IF; IF char_length(_name) NOT BETWEEN 2 AND 120 OR char_length(coalesce(_description,''))>600 THEN RAISE EXCEPTION 'Nombre o descripción inválidos'; END IF; IF _parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.departments WHERE id=_parent_id AND is_active) THEN RAISE EXCEPTION 'Departamento superior inválido o inactivo'; END IF; PERFORM pg_advisory_xact_lock(170012); IF EXISTS(SELECT 1 FROM public.departments WHERE lower(btrim(name))=lower(_name) AND id IS DISTINCT FROM _id) THEN RAISE EXCEPTION 'Ya existe un departamento con ese nombre'; END IF; IF _id IS NULL THEN INSERT INTO public.departments(code,name,description,sort_order,parent_id) VALUES(_code,_name,coalesce(_description,''),coalesce(_sort,0),_parent_id) RETURNING id INTO rid; PERFORM public.org_log('departamento.crear','departamento',rid::text,NULL,jsonb_build_object('code',_code,'name',_name,'parent_id',_parent_id),NULL); ELSE SELECT * INTO old FROM public.departments WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Departamento no encontrado'; END IF; IF old.code='direccion' AND (_code<>'direccion' OR _parent_id IS NOT NULL) THEN RAISE EXCEPTION 'Dirección Ejecutiva es la raíz reservada'; END IF; UPDATE public.departments SET code=_code,name=_name,description=coalesce(_description,''),sort_order=coalesce(_sort,sort_order),parent_id=_parent_id,updated_at=now() WHERE id=_id; rid:=_id; PERFORM public.org_log('departamento.editar','departamento',rid::text,to_jsonb(old),jsonb_build_object('code',_code,'name',_name,'parent_id',_parent_id),NULL); END IF; RETURN rid; END $$;
CREATE FUNCTION public.org_set_department_active(_id uuid,_active boolean,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('departamentos'); d public.departments; BEGIN PERFORM public.org_need_reason(_reason); SELECT * INTO d FROM public.departments WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Departamento no encontrado'; END IF; IF d.code='direccion' AND NOT _active THEN RAISE EXCEPTION 'Dirección Ejecutiva no puede desactivarse'; END IF; IF NOT _active AND EXISTS(SELECT 1 FROM public.departments WHERE parent_id=_id AND is_active) THEN RAISE EXCEPTION 'Desactiva primero los departamentos dependientes'; END IF; IF NOT _active AND EXISTS(SELECT 1 FROM public.org_user_positions up JOIN public.org_positions p ON p.id=up.position_id WHERE up.ended_at IS NULL AND (up.department_id=_id OR (up.department_id IS NULL AND p.department_id=_id))) THEN RAISE EXCEPTION 'Finaliza primero las asignaciones de cargos vigentes de este departamento'; END IF; UPDATE public.departments SET is_active=_active,updated_at=now() WHERE id=_id; PERFORM public.org_log(CASE WHEN _active THEN 'departamento.activar' ELSE 'departamento.desactivar' END,'departamento',_id::text,jsonb_build_object('is_active',d.is_active),jsonb_build_object('is_active',_active),_reason); END $$;
CREATE FUNCTION public.org_set_department_head(_dept uuid,_user uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('departamentos'); d public.departments; BEGIN PERFORM public.org_need_reason(_reason); SELECT * INTO d FROM public.departments WHERE id=_dept AND is_active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Departamento no encontrado o inactivo'; END IF; IF _user IS NOT NULL THEN IF NOT public.org_is_active_user(_user) THEN RAISE EXCEPTION 'El responsable debe ser un usuario activo'; END IF; IF d.code='direccion' THEN IF NOT public.is_ceo(_user) THEN RAISE EXCEPTION 'Dirección Ejecutiva solo puede ser dirigida por el CEO'; END IF; ELSIF public.org_user_dept(_user) IS DISTINCT FROM _dept THEN RAISE EXCEPTION 'El responsable debe ser miembro del departamento'; END IF; END IF; UPDATE public.departments SET head_user_id=_user,updated_at=now() WHERE id=_dept; PERFORM public.org_log('departamento.responsable','departamento',_dept::text,jsonb_build_object('head_user_id',d.head_user_id),jsonb_build_object('head_user_id',_user),_reason); END $$;
CREATE FUNCTION public.org_set_user_department(_user uuid,_department uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('departamentos'); old_dept uuid; d public.departments; BEGIN PERFORM public.org_need_reason(_reason); IF _user=actor THEN RAISE EXCEPTION 'No puedes modificar tu propio departamento'; END IF; SELECT * INTO d FROM public.departments WHERE id=_department AND is_active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Departamento no encontrado o inactivo'; END IF; IF d.code='direccion' AND NOT public.is_ceo(_user) THEN RAISE EXCEPTION 'Dirección Ejecutiva está reservada al CEO'; END IF; SELECT department_id INTO old_dept FROM public.profiles WHERE id=_user FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Usuario no encontrado'; END IF; IF old_dept IS NOT DISTINCT FROM _department THEN RAISE EXCEPTION 'La persona ya pertenece a ese departamento'; END IF; UPDATE public.profiles SET department_id=_department WHERE id=_user; UPDATE public.departments SET head_user_id=NULL,updated_at=now() WHERE id=old_dept AND head_user_id=_user; PERFORM public.org_log('usuario.departamento','usuario',_user::text,jsonb_build_object('department_id',old_dept),jsonb_build_object('department_id',_department),_reason); END $$;
CREATE FUNCTION public.org_upsert_position(_id uuid,_code text,_name text,_description text,_department_id uuid,_reports_to_id uuid,_responsibilities text[],_is_external boolean,_sort int) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('cargos'); old public.org_positions; rid uuid; resp text[]; BEGIN _code:=lower(btrim(coalesce(_code,''))); _name:=btrim(coalesce(_name,'')); IF _code !~ '^[a-z0-9_]{2,50}$' OR char_length(_name) NOT BETWEEN 2 AND 120 OR char_length(coalesce(_description,''))>600 THEN RAISE EXCEPTION 'Código, nombre o descripción inválidos'; END IF; resp:=coalesce((SELECT array_agg(btrim(x)) FROM unnest(coalesce(_responsibilities,'{}')) x WHERE char_length(btrim(x)) BETWEEN 1 AND 300),'{}'); IF array_length(resp,1)>20 THEN RAISE EXCEPTION 'Máximo 20 responsabilidades'; END IF; IF _department_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.departments WHERE id=_department_id AND is_active) THEN RAISE EXCEPTION 'Departamento inválido o inactivo'; END IF; IF _reports_to_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.org_positions WHERE id=_reports_to_id AND is_active) THEN RAISE EXCEPTION 'Cargo superior inválido o inactivo'; END IF; IF _id IS NULL THEN INSERT INTO public.org_positions(code,name,description,department_id,reports_to_id,responsibilities,is_external,sort_order) VALUES(_code,_name,coalesce(_description,''),_department_id,_reports_to_id,resp,coalesce(_is_external,false),coalesce(_sort,0)) RETURNING id INTO rid; PERFORM public.org_log('cargo.crear','cargo',rid::text,NULL,jsonb_build_object('code',_code,'name',_name,'department_id',_department_id,'reports_to_id',_reports_to_id),NULL); ELSE SELECT * INTO old FROM public.org_positions WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Cargo no encontrado'; END IF; IF old.code='ceo' AND (_code<>'ceo' OR _reports_to_id IS NOT NULL OR _is_external OR _department_id IS DISTINCT FROM old.department_id) THEN RAISE EXCEPTION 'El cargo CEO es la raíz reservada'; END IF; UPDATE public.org_positions SET code=_code,name=_name,description=coalesce(_description,''),department_id=_department_id,reports_to_id=_reports_to_id,responsibilities=resp,is_external=coalesce(_is_external,false),sort_order=coalesce(_sort,sort_order),updated_at=now() WHERE id=_id; rid:=_id; PERFORM public.org_log('cargo.editar','cargo',rid::text,to_jsonb(old),jsonb_build_object('name',_name,'department_id',_department_id,'reports_to_id',_reports_to_id),NULL); END IF; RETURN rid; END $$;
CREATE FUNCTION public.org_set_position_active(_id uuid,_active boolean,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('cargos'); p public.org_positions; BEGIN PERFORM public.org_need_reason(_reason); SELECT * INTO p FROM public.org_positions WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Cargo no encontrado'; END IF; IF p.code='ceo' AND NOT _active THEN RAISE EXCEPTION 'El cargo CEO no puede desactivarse'; END IF; IF NOT _active AND EXISTS(SELECT 1 FROM public.org_user_positions WHERE position_id=_id AND ended_at IS NULL) THEN RAISE EXCEPTION 'Finaliza primero las asignaciones vigentes de este cargo'; END IF; UPDATE public.org_positions SET is_active=_active,updated_at=now() WHERE id=_id; PERFORM public.org_log(CASE WHEN _active THEN 'cargo.activar' ELSE 'cargo.desactivar' END,'cargo',_id::text,jsonb_build_object('is_active',p.is_active),jsonb_build_object('is_active',_active),_reason); END $$;
CREATE FUNCTION public.org_set_position_roles(_position uuid,_role_ids uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('cargos'); before_ids uuid[]; rid uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.org_positions WHERE id=_position) THEN RAISE EXCEPTION 'Cargo no encontrado'; END IF; _role_ids:=coalesce((SELECT array_agg(DISTINCT x) FROM unnest(coalesce(_role_ids,'{}')) x),'{}'); FOREACH rid IN ARRAY _role_ids LOOP IF NOT EXISTS(SELECT 1 FROM public.org_roles WHERE id=rid AND is_active) THEN RAISE EXCEPTION 'Rol inválido o inactivo en la plantilla'; END IF; END LOOP; SELECT coalesce(array_agg(role_id),'{}') INTO before_ids FROM public.org_position_roles WHERE position_id=_position; DELETE FROM public.org_position_roles WHERE position_id=_position; INSERT INTO public.org_position_roles(position_id,role_id) SELECT _position,x FROM unnest(_role_ids) x; PERFORM public.org_log('cargo.roles_sugeridos','cargo',_position::text,jsonb_build_object('role_ids',before_ids),jsonb_build_object('role_ids',_role_ids),NULL); END $$;
CREATE FUNCTION public.org_assign_position(_user uuid,_position uuid,_department uuid,_is_primary boolean,_ends_at date,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('cargos'); p public.org_positions; nid uuid; c record; mine uuid[]; theirs uuid[]; BEGIN PERFORM public.org_need_reason(_reason); IF _user=actor THEN RAISE EXCEPTION 'No puedes asignarte cargos a ti mismo'; END IF; PERFORM 1 FROM public.profiles WHERE id=_user FOR UPDATE; IF NOT public.org_is_active_user(_user) THEN RAISE EXCEPTION 'El usuario destino no está activo'; END IF; SELECT * INTO p FROM public.org_positions WHERE id=_position AND is_active; IF NOT FOUND THEN RAISE EXCEPTION 'Cargo no encontrado o inactivo'; END IF; IF p.code='ceo' AND NOT public.is_ceo(_user) THEN RAISE EXCEPTION 'El cargo CEO solo puede ocuparlo el CEO autorizado'; END IF; IF _ends_at IS NOT NULL AND _ends_at<=current_date THEN RAISE EXCEPTION 'La fecha de fin debe ser futura'; END IF; IF coalesce(_department,p.department_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.departments WHERE id=coalesce(_department,p.department_id) AND is_active) THEN RAISE EXCEPTION 'Departamento inválido o inactivo'; END IF; IF EXISTS(SELECT 1 FROM public.departments WHERE id=coalesce(_department,p.department_id) AND code='direccion') AND NOT public.is_ceo(_user) THEN RAISE EXCEPTION 'Dirección Ejecutiva está reservada al CEO'; END IF; SELECT coalesce(array_agg(role_id),'{}') INTO mine FROM public.org_position_roles WHERE position_id=_position; SELECT coalesce(array_agg(pr.role_id),'{}') INTO theirs FROM public.org_user_positions up JOIN public.org_position_roles pr ON pr.position_id=up.position_id WHERE up.user_id=_user AND up.ended_at IS NULL; FOR c IN SELECT * FROM public.org_sod_conflicts_if(_user,mine,theirs) LOOP RAISE EXCEPTION 'Conflicto de funciones (%): %',c.severity,c.description; END LOOP; IF coalesce(_is_primary,false) THEN UPDATE public.org_user_positions SET is_primary=false WHERE user_id=_user AND ended_at IS NULL; END IF; INSERT INTO public.org_user_positions(user_id,position_id,department_id,is_primary,ends_at,assigned_by) VALUES(_user,_position,coalesce(_department,p.department_id),coalesce(_is_primary,false),_ends_at,actor) RETURNING id INTO nid; PERFORM public.org_log('cargo.asignar','usuario',_user::text,NULL,jsonb_build_object('position_id',_position,'assignment_id',nid),_reason); RETURN nid; END $$;
CREATE FUNCTION public.org_end_position(_assignment uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('cargos'); a public.org_user_positions; BEGIN PERFORM public.org_need_reason(_reason); SELECT * INTO a FROM public.org_user_positions WHERE id=_assignment AND ended_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Asignación no encontrada o ya finalizada'; END IF; IF a.user_id=actor THEN RAISE EXCEPTION 'No puedes modificar tus propios cargos'; END IF; UPDATE public.org_user_positions SET ended_at=now(),end_reason=_reason,is_primary=false WHERE id=_assignment; PERFORM public.org_log('cargo.finalizar','usuario',a.user_id::text,jsonb_build_object('position_id',a.position_id),NULL,_reason); END $$;
CREATE FUNCTION public.org_upsert_role(_id uuid,_code text,_name text,_description text,_is_privileged boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('roles'); old public.org_roles; rid uuid; BEGIN _code:=lower(btrim(coalesce(_code,''))); _name:=btrim(coalesce(_name,'')); IF _code !~ '^[a-z0-9_]{3,50}$' OR char_length(_name) NOT BETWEEN 2 AND 120 OR char_length(coalesce(_description,''))>600 THEN RAISE EXCEPTION 'Código, nombre o descripción inválidos'; END IF; IF _id IS NULL THEN INSERT INTO public.org_roles(code,name,description,is_privileged,created_by) VALUES(_code,_name,coalesce(_description,''),coalesce(_is_privileged,false),actor) RETURNING id INTO rid; PERFORM public.org_log('rol.crear','rol',rid::text,NULL,jsonb_build_object('code',_code,'name',_name),NULL); ELSE SELECT * INTO old FROM public.org_roles WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Rol no encontrado'; END IF; IF old.is_system AND _code<>old.code THEN RAISE EXCEPTION 'No se puede cambiar el código de un rol del sistema'; END IF; UPDATE public.org_roles SET code=_code,name=_name,description=coalesce(_description,''),is_privileged=coalesce(_is_privileged,is_privileged),updated_at=now() WHERE id=_id; rid:=_id; PERFORM public.org_log('rol.editar','rol',rid::text,to_jsonb(old),jsonb_build_object('name',_name,'is_privileged',coalesce(_is_privileged,old.is_privileged)),NULL); END IF; RETURN rid; END $$;
CREATE FUNCTION public.org_set_role_active(_id uuid,_active boolean,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('roles'); r public.org_roles; BEGIN PERFORM public.org_need_reason(_reason); SELECT * INTO r FROM public.org_roles WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Rol no encontrado'; END IF; UPDATE public.org_roles SET is_active=_active,updated_at=now() WHERE id=_id; PERFORM public.org_log(CASE WHEN _active THEN 'rol.activar' ELSE 'rol.desactivar' END,'rol',_id::text,jsonb_build_object('is_active',r.is_active),jsonb_build_object('is_active',_active),_reason); END $$;
CREATE FUNCTION public.org_set_role_permission(_role uuid,_permission uuid,_enabled boolean,_require_mfa boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('permisos'); p public.org_permissions; BEGIN IF NOT EXISTS(SELECT 1 FROM public.org_roles WHERE id=_role) THEN RAISE EXCEPTION 'Rol no encontrado'; END IF; SELECT * INTO p FROM public.org_permissions WHERE id=_permission; IF NOT FOUND THEN RAISE EXCEPTION 'Permiso no encontrado'; END IF; IF _enabled THEN INSERT INTO public.org_role_permissions(role_id,permission_id,require_mfa,granted_by) VALUES(_role,_permission,coalesce(_require_mfa,false),actor) ON CONFLICT(role_id,permission_id) DO UPDATE SET require_mfa=excluded.require_mfa,granted_by=excluded.granted_by; ELSE DELETE FROM public.org_role_permissions WHERE role_id=_role AND permission_id=_permission; END IF; PERFORM public.org_log(CASE WHEN _enabled THEN 'rol.permiso_otorgado' ELSE 'rol.permiso_revocado' END,'rol',_role::text,NULL,jsonb_build_object('resource',p.resource,'action',p.action,'scope',p.scope,'require_mfa',coalesce(_require_mfa,false)),NULL); END $$;
CREATE FUNCTION public.org_assign_role(_user uuid,_role uuid,_department uuid,_valid_until timestamptz,_justification text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('roles'); eff_dept uuid; has_dept boolean; nid uuid; c record; BEGIN IF _user=actor THEN RAISE EXCEPTION 'No puedes asignarte roles a ti mismo'; END IF; IF char_length(btrim(coalesce(_justification,'')))<10 THEN RAISE EXCEPTION 'La justificación debe tener al menos 10 caracteres'; END IF; PERFORM 1 FROM public.profiles WHERE id=_user FOR UPDATE; IF NOT public.org_is_active_user(_user) THEN RAISE EXCEPTION 'El usuario destino no está activo'; END IF; IF public.is_ceo(_user) THEN RAISE EXCEPTION 'El CEO no requiere roles funcionales'; END IF; IF NOT EXISTS(SELECT 1 FROM public.org_roles WHERE id=_role AND is_active) THEN RAISE EXCEPTION 'Rol no encontrado o inactivo'; END IF; IF _valid_until IS NOT NULL AND _valid_until<=now() THEN RAISE EXCEPTION 'La vigencia debe ser futura'; END IF; SELECT EXISTS(SELECT 1 FROM public.org_role_permissions rp JOIN public.org_permissions p ON p.id=rp.permission_id WHERE rp.role_id=_role AND p.scope='departamento') INTO has_dept; eff_dept:=CASE WHEN has_dept THEN coalesce(_department,public.org_user_dept(_user)) END; IF has_dept AND eff_dept IS NULL THEN RAISE EXCEPTION 'El rol tiene alcance departamental: indica un departamento'; END IF; IF eff_dept IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.departments WHERE id=eff_dept AND is_active) THEN RAISE EXCEPTION 'Departamento inválido o inactivo'; END IF; FOR c IN SELECT * FROM public.org_sod_conflicts_if(_user,array[_role]) LOOP RAISE EXCEPTION 'Conflicto de funciones (%): %. Requiere una excepción aprobada por el CEO.',c.severity,c.description; END LOOP; INSERT INTO public.org_user_roles(user_id,role_id,department_id,justification,valid_until,granted_by) VALUES(_user,_role,eff_dept,btrim(_justification),_valid_until,actor) RETURNING id INTO nid; PERFORM public.org_log('rol.asignar','usuario',_user::text,NULL,jsonb_build_object('role_id',_role,'assignment_id',nid,'department_id',eff_dept,'valid_until',_valid_until),_justification); RETURN nid; END $$;
CREATE FUNCTION public.org_revoke_role(_assignment uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('roles'); a public.org_user_roles; BEGIN PERFORM public.org_need_reason(_reason); SELECT * INTO a FROM public.org_user_roles WHERE id=_assignment AND revoked_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Asignación no encontrada o ya revocada'; END IF; IF a.user_id=actor THEN RAISE EXCEPTION 'No puedes modificar tus propios roles'; END IF; UPDATE public.org_user_roles SET revoked_at=now(),revoked_by=actor,revoke_reason=_reason WHERE id=_assignment; PERFORM public.org_log('rol.revocar','usuario',a.user_id::text,jsonb_build_object('role_id',a.role_id,'assignment_id',_assignment),NULL,_reason); END $$;
CREATE FUNCTION public.org_set_user_deny(_user uuid,_permission uuid,_deny boolean,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('permisos'); p public.org_permissions; BEGIN PERFORM public.org_need_reason(_reason); IF _user=actor THEN RAISE EXCEPTION 'No puedes modificar tus propias restricciones'; END IF; SELECT * INTO p FROM public.org_permissions WHERE id=_permission; IF NOT FOUND THEN RAISE EXCEPTION 'Permiso no encontrado'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user) THEN RAISE EXCEPTION 'Usuario no encontrado'; END IF; IF _deny THEN INSERT INTO public.org_user_denies(user_id,permission_id,reason,created_by) VALUES(_user,_permission,btrim(_reason),actor) ON CONFLICT(user_id,permission_id) DO UPDATE SET reason=excluded.reason,created_by=excluded.created_by; ELSE DELETE FROM public.org_user_denies WHERE user_id=_user AND permission_id=_permission; END IF; PERFORM public.org_log(CASE WHEN _deny THEN 'usuario.denegar_permiso' ELSE 'usuario.levantar_denegacion' END,'usuario',_user::text,NULL,jsonb_build_object('resource',p.resource,'action',p.action,'scope',p.scope),_reason); END $$;
CREATE FUNCTION public.org_create_sod_exception(_kind text,_user uuid,_rule uuid,_policy text,_record text,_justification text,_days int) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('roles'); nid uuid; BEGIN IF _user=actor THEN RAISE EXCEPTION 'No puedes concederte una excepción a ti mismo'; END IF; IF char_length(btrim(coalesce(_justification,'')))<20 THEN RAISE EXCEPTION 'La justificación debe tener al menos 20 caracteres'; END IF; IF _days IS NULL OR _days<1 OR _days>90 THEN RAISE EXCEPTION 'La vigencia de una excepción es de 1 a 90 días'; END IF; IF NOT public.org_is_active_user(_user) THEN RAISE EXCEPTION 'Usuario inválido'; END IF; IF _kind='rol' AND NOT EXISTS(SELECT 1 FROM public.org_sod_rules WHERE id=_rule AND is_active) THEN RAISE EXCEPTION 'Regla no encontrada'; END IF; IF _kind='operacion' AND NOT EXISTS(SELECT 1 FROM public.org_sod_policies WHERE code=_policy) THEN RAISE EXCEPTION 'Política no encontrada'; END IF; INSERT INTO public.org_sod_exceptions(kind,user_id,rule_id,policy_code,record_ref,justification,approved_by,expires_at) VALUES(_kind,_user,CASE WHEN _kind='rol' THEN _rule END,CASE WHEN _kind='operacion' THEN _policy END,nullif(btrim(coalesce(_record,'')),''),btrim(_justification),actor,now()+make_interval(days=>_days)) RETURNING id INTO nid; PERFORM public.org_log('sod.excepcion_crear','usuario',_user::text,NULL,jsonb_build_object('exception_id',nid,'kind',_kind,'rule_id',_rule,'policy',_policy,'days',_days),_justification); RETURN nid; END $$;
CREATE FUNCTION public.org_revoke_sod_exception(_id uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor uuid:=public.org_assert_admin('roles'); e public.org_sod_exceptions; BEGIN PERFORM public.org_need_reason(_reason); SELECT * INTO e FROM public.org_sod_exceptions WHERE id=_id AND revoked_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Excepción no encontrada o ya revocada'; END IF; IF e.user_id=actor THEN RAISE EXCEPTION 'No puedes modificar tus propias excepciones'; END IF; UPDATE public.org_sod_exceptions SET revoked_at=now(),revoked_by=actor WHERE id=_id; PERFORM public.org_log('sod.excepcion_revocar','usuario',e.user_id::text,jsonb_build_object('exception_id',_id),NULL,_reason); END $$;
CREATE FUNCTION public.org_log_denied(_action text,_entity text,_entity_id text,_error text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE u uuid:=auth.uid(); BEGIN IF u IS NULL OR NOT public.org_is_active_user(u) THEN RETURN; END IF; IF coalesce(_action,'') !~ '^[a-z_.]{2,60}$' OR coalesce(_entity,'') !~ '^[a-z_]{2,40}$' THEN RETURN; END IF; IF (SELECT count(*) FROM public.org_change_log WHERE actor_id=u AND result='denegado' AND created_at>now()-interval '1 hour')>=100 THEN RETURN; END IF; INSERT INTO public.org_change_log(actor_id,actor_email,action,entity,entity_id,reason,result) VALUES(u,(SELECT email FROM public.profiles WHERE id=u),_action,_entity,left(_entity_id,120),left(coalesce(_error,''),300),'denegado'); PERFORM public.write_audit('org.'||_action||'.denegado',_entity||':'||coalesce(left(_entity_id,120),''),jsonb_build_object('reason',left(coalesce(_error,''),300))); END $$;
CREATE FUNCTION public.org_check_me(_resource text,_action public.org_action,_dept uuid DEFAULT NULL,_owner uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT public.org_check(auth.uid(),_resource,_action,_dept,_owner,false) $$;
CREATE FUNCTION public.org_can_read_catalog() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT public.org_is_active_user(auth.uid()) AND (public.is_ceo(auth.uid()) OR public.org_check(auth.uid(),'roles','consultar',NULL,NULL,true) OR public.org_check(auth.uid(),'permisos','consultar',NULL,NULL,true) OR public.org_check(auth.uid(),'cargos','consultar',NULL,NULL,true)) $$;
CREATE FUNCTION public.org_can_see_user(_target uuid,_resource text,_global_only boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT public.org_is_active_user(auth.uid()) AND (_target=auth.uid() OR public.is_ceo(auth.uid()) OR public.org_check(auth.uid(),_resource,'consultar',CASE WHEN _global_only THEN NULL ELSE public.org_user_dept(_target) END,_target)) $$;
CREATE FUNCTION public.org_can_audit() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT public.org_is_active_user(auth.uid()) AND (public.is_ceo(auth.uid()) OR public.org_check(auth.uid(),'auditoria','consultar',NULL,NULL)) $$;
CREATE FUNCTION public.org_list_users() RETURNS TABLE(id uuid,email text,full_name text,department_id uuid,status public.account_status,is_ceo boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE u uuid:=public.org_actor(); BEGIN RETURN QUERY SELECT p.id,p.email,p.full_name,p.department_id,p.status,public.is_ceo(p.id) FROM public.profiles p WHERE p.id=u OR public.is_ceo(u) OR public.org_check(u,'usuarios','consultar',p.department_id,p.id) ORDER BY p.full_name,p.email; END $$;
DO $$ DECLARE f record; BEGIN FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'org_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM public,anon,authenticated',f.sig); END LOOP; END $$;
DO $$ DECLARE f text; BEGIN FOREACH f IN ARRAY ARRAY['org_my_permissions()','org_user_effective_permissions(uuid)','org_user_conflicts(uuid)','org_upsert_department(uuid,text,text,text,uuid,int)','org_set_department_active(uuid,boolean,text)','org_set_department_head(uuid,uuid,text)','org_set_user_department(uuid,uuid,text)','org_upsert_position(uuid,text,text,text,uuid,uuid,text[],boolean,int)','org_set_position_active(uuid,boolean,text)','org_set_position_roles(uuid,uuid[])','org_assign_position(uuid,uuid,uuid,boolean,date,text)','org_end_position(uuid,text)','org_upsert_role(uuid,text,text,text,boolean)','org_set_role_active(uuid,boolean,text)','org_set_role_permission(uuid,uuid,boolean,boolean)','org_assign_role(uuid,uuid,uuid,timestamptz,text)','org_revoke_role(uuid,text)','org_set_user_deny(uuid,uuid,boolean,text)','org_create_sod_exception(text,uuid,uuid,text,text,text,int)','org_revoke_sod_exception(uuid,text)','org_log_denied(text,text,text,text)','org_check_me(text,public.org_action,uuid,uuid)','org_can_read_catalog()','org_can_see_user(uuid,text,boolean)','org_can_audit()','org_list_users()'] LOOP EXECUTE format('GRANT EXECUTE ON FUNCTION public.%s TO authenticated',f); END LOOP; END $$;
CREATE POLICY "org catalog read" ON public.org_resources FOR SELECT TO authenticated USING(public.org_can_read_catalog());
CREATE POLICY "org perm read" ON public.org_permissions FOR SELECT TO authenticated USING(public.org_can_read_catalog());
CREATE POLICY "org roles read" ON public.org_roles FOR SELECT TO authenticated USING(public.org_can_read_catalog());
CREATE POLICY "org rp read" ON public.org_role_permissions FOR SELECT TO authenticated USING(public.org_can_read_catalog());
CREATE POLICY "org pos read" ON public.org_positions FOR SELECT TO authenticated USING(public.org_can_read_catalog());
CREATE POLICY "org posroles read" ON public.org_position_roles FOR SELECT TO authenticated USING(public.org_can_read_catalog());
CREATE POLICY "org sodrules read" ON public.org_sod_rules FOR SELECT TO authenticated USING(public.org_can_read_catalog());
CREATE POLICY "org sodpol read" ON public.org_sod_policies FOR SELECT TO authenticated USING(public.org_can_read_catalog());
CREATE POLICY "org userpos read" ON public.org_user_positions FOR SELECT TO authenticated USING(public.org_can_see_user(user_id,'usuarios') OR public.org_can_see_user(user_id,'cargos'));
CREATE POLICY "org userroles read" ON public.org_user_roles FOR SELECT TO authenticated USING(public.org_can_see_user(user_id,'usuarios') OR public.org_can_see_user(user_id,'roles',true));
CREATE POLICY "org denies read" ON public.org_user_denies FOR SELECT TO authenticated USING(public.org_can_see_user(user_id,'permisos',true));
CREATE POLICY "org exceptions read" ON public.org_sod_exceptions FOR SELECT TO authenticated USING(public.org_can_see_user(user_id,'roles',true));
CREATE POLICY "org changelog read" ON public.org_change_log FOR SELECT TO authenticated USING(public.org_can_audit());
CREATE POLICY "org steps read" ON public.org_operation_steps FOR SELECT TO authenticated USING(public.org_can_audit());
CREATE POLICY "org legacy map read" ON public.org_legacy_map FOR SELECT TO authenticated USING(public.org_can_read_catalog());